library(shiny)
library(bslib)
library(htmltools)

ui <- page_navbar(
  title = tags$span(
    tags$strong("STAT 3110"), 
    " | Vector Discovery Lab"
  ),
  id = "main_nav",
  theme = bs_theme(
    version = 5,
    bootswatch = "flatly",
    primary = "#1e293b",
    secondary = "#475569",
    success = "#16a34a",
    info = "#2563eb"
  ),
  header = tags$head(
    tags$style(HTML("
      body { background-color: #f8fafc; }
      .canvas-wrap {
        position: relative;
        width: 100%;
        background: #ffffff;
        border: 1px solid #cbd5e1;
        border-radius: 10px;
        box-shadow: inset 0 1px 3px rgba(0,0,0,0.04);
        overflow: hidden;
        touch-action: none;
        user-select: none;
      }
      canvas.lab-canvas {
        display: block;
        width: 100%;
        height: 460px;
        cursor: grab;
      }
      canvas.lab-canvas:active {
        cursor: grabbing;
      }
      .hud-banner {
        background: #f1f5f9;
        border-left: 4px solid #2563eb;
        padding: 10px 14px;
        border-radius: 6px;
        font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
        font-size: 0.92rem;
        margin-bottom: 12px;
      }
      .status-pill {
        display: inline-block;
        padding: 6px 12px;
        border-radius: 999px;
        font-weight: 600;
        font-size: 0.88rem;
      }
      .status-match { background: #dcfce7; color: #166534; border: 1px solid #86efac; }
      .status-partial { background: #fef9c3; color: #854d0e; border: 1px solid #fde047; }
      .status-wait { background: #f1f5f9; color: #475569; border: 1px solid #cbd5e1; }
      .disc-box {
        background: #ffffff;
        border: 1px solid #e2e8f0;
        border-left: 4px solid #0f172a;
        border-radius: 8px;
        padding: 14px 18px;
        margin-top: 12px;
      }
      .disc-box h6 {
        font-weight: 700;
        color: #0f172a;
        margin-bottom: 8px;
      }
      .disc-box ol {
        margin-bottom: 0;
        padding-left: 1.2rem;
      }
      .disc-box li {
        margin-bottom: 6px;
        font-size: 0.94rem;
      }
      .math-badge {
        background: #e2e8f0;
        padding: 2px 7px;
        border-radius: 4px;
        font-weight: 600;
      }
      .stop-banner {
        background: #fffbeb;
        border: 1px solid #fde68a;
        color: #92400e;
        padding: 8px 14px;
        border-radius: 6px;
        font-size: 0.88rem;
        font-weight: 600;
        margin-top: 10px;
        text-align: center;
      }
    "))
  ),
  
  # =========================================================================
  # PANEL 1: ANATOMY OF A VECTOR (COMMUNICATION GAME)
  # =========================================================================
  nav_panel(
    title = "1. Anatomy of a Vector",
    layout_sidebar(
      sidebar = sidebar(
        width = 330,
        h5("The Communication Game"),
        p(class = "text-muted small",
          "One group member chooses a Puzzle ID in ", tags$b("Sender"), 
          " mode and describes the vector to the rest of the group in ", 
          tags$b("Receiver"), " mode."),
        selectInput(
          "p1_puzzle", "Select Puzzle ID (1 - 20):",
          choices = setNames(1:20, paste("Puzzle #", 1:20)),
          selected = 1
        ),
        radioButtons(
          "p1_role", "Your Group Role:",
          choices = c(
            "Receiver (Build & Match)" = "receiver",
            "Sender (View Target Vector)" = "sender"
          ),
          selected = "receiver"
        ),
        hr(),
        radioButtons(
          "p1_match_mode", "Match Rule:",
          choices = c(
            "Round 1: Exact Grid Position" = "exact",
            "Round 2: True Vector (Any Start Position)" = "vector"
          ),
          selected = "exact"
        ),
        checkboxInput("p1_show_coords", "Show Coordinate Labels on Grid", value = FALSE),
        actionButton("p1_origin_btn", "Snap My Vector Tail to Origin (0,0)", 
                     class = "btn-outline-primary btn-sm w-100 mt-1"),
        actionButton("p1_reset_btn", "Reset Receiver Vector", 
                     class = "btn-outline-secondary btn-sm w-100 mt-2")
      ),
      div(
        div(
          class = "d-flex justify-content-between align-items-center flex-wrap gap-2 mb-2",
          div(id = "p1_status_badge", class = "status-pill status-wait", "Drag the tail, tip, or body of the vector"),
          div(id = "p1_hud", class = "hud-banner mb-0 py-1 px-3", "")
        ),
        div(
          class = "canvas-wrap",
          tags$canvas(id = "canvas_p1", class = "lab-canvas")
        ),
        div(
          class = "disc-box",
          tags$h6("Group Discussion Prompts (Panel 1)"),
          tags$ol(
            tags$li(tags$b("Round 1 (Exact Grid Position):"), " What is the minimum amount of information the Sender had to say out loud for the Receivers to place the arrow in the exact same spot on the grid?"),
            tags$li(tags$b("Round 2 (True Vector Mode):"), " Switch to 'True Vector' mode. Once your arrow matches, grab the ", tags$i("middle shaft"), " of your arrow and slide it all over the grid. Why does the app still mark it as the exact same vector? What information do you actually need to communicate a 2D vector?"),
            tags$li(tags$b("Standard Position & Magnitude:"), " Click 'Snap My Vector Tail to Origin (0,0)'. Why is starting at the origin the most convenient convention? Using the horizontal and vertical components, what formula gives the exact length (magnitude ", HTML("||<b>v</b>||"), ") of the vector?")
          ),
          div(class = "stop-banner", "PAUSE HERE: Compare your group's rules with the class before moving to Panel 2.")
        )
      )
    )
  ),
  
  # =========================================================================
  # PANEL 2: GEOMETRIC OPERATIONS (SCALING, ADDITION, SUBTRACTION)
  # =========================================================================
  nav_panel(
    title = "2. Scaling, Addition & Subtraction",
    layout_sidebar(
      sidebar = sidebar(
        width = 330,
        h5("Geometric Vector Operations"),
        radioButtons(
          "p2_mode", "Choose Operation to Explore:",
          choices = c(
            "Scalar Multiplication (λv)" = "scale",
            "Vector Addition (a + b)" = "add",
            "Vector Subtraction (a - b)" = "sub"
          ),
          selected = "scale"
        ),
        selectInput(
          "p2_preset", "Vector Pair Preset:",
          choices = c(
            "Preset 1: a = (3, 1), b = (1, 3)" = "1",
            "Preset 2: a = (4, 2), b = (-2, 3)" = "2",
            "Preset 3: a = (-3, 2), b = (4, 1)" = "3",
            "Preset 4: a = (2, -3), b = (3, 2)" = "4"
          )
        ),
        conditionalPanel(
          condition = "input.p2_mode == 'scale'",
          div(
            class = "p-3 mb-2 rounded border bg-light text-center",
            div(class = "text-muted small fw-bold", "LIVE SCALAR MULTIPLIER"),
            div(id = "p2_lambda_display", class = "fs-3 fw-bold text-primary", "λ = 1.00")
          ),
          p(class = "text-muted small", 
            "Grab and drag the blue tip of ", HTML("<b>&lambda;v</b>"), 
            " directly along the dashed line on the canvas to stretch, shrink, or flip it.")
        ),
        conditionalPanel(
          condition = "input.p2_mode != 'scale'",
          p(class = "text-muted small",
            "All vectors start at the origin (0,0). ",
            tags$b("Grab and drag the body of any vector"), 
            " to translate it across the grid until they lock together into a closed triangle!"),
          checkboxInput("p2_flip_b", "Show / Flip b into -b (Reverse Direction)", value = FALSE),
          actionButton("p2_reset_pos", "Return All Vectors to Origin (0,0)", 
                       class = "btn-outline-secondary btn-sm w-100 mt-1")
        )
      ),
      div(
        div(
          class = "d-flex justify-content-between align-items-center flex-wrap gap-2 mb-2",
          div(id = "p2_status_badge", class = "status-pill status-wait", "Explore the geometric operation"),
          div(id = "p2_hud", class = "hud-banner mb-0 py-1 px-3", "")
        ),
        div(
          class = "canvas-wrap",
          tags$canvas(id = "canvas_p2", class = "lab-canvas")
        ),
        div(
          class = "disc-box",
          tags$h6("Group Discussion Prompts (Panel 2)"),
          tags$ol(
            tags$li(tags$b("Scalar Multiplication (λv):"), " Match the dashed target vector by dragging the tip of ", HTML("<b>&lambda;v</b>"), ". Which values of ", HTML("&lambda;"), " stretch the vector? Which values shrink it? What happens when ", HTML("&lambda; < 0"), ", and can any scalar multiplier ever rotate ", HTML("<b>v</b>"), " off its dashed line of action?"),
            tags$li(tags$b("Addition (a + b):"), " Switch to Addition. Slide the vectors around to uncover a geometric interpretation of vector addition. What does it mean to add two vectors geometrically?"),
            tags$li(tags$b("Subtraction (a - b):"), " Switch to Subtraction. Find two different ways to form a closed triangle. How does your group interpret each triangle?")
          ),
          div(class = "stop-banner", "PAUSE HERE: Be ready to sketch your head-to-tail and subtraction triangles before moving to Panel 3.")
        )
      )
    )
  ),
  
  # =========================================================================
  # PANEL 3: ANGLE <-> DOT PRODUCT LAB (NO PROJECTIONS)
  # =========================================================================
  nav_panel(
    title = "3. Angle & Dot Product",
    layout_sidebar(
      sidebar = sidebar(
        width = 330,
        h5("Angle ↔ Dot Product Discovery"),
        p(class = "text-muted small",
          "Drag the tips of vectors ", HTML("<b>a</b>"), " (blue) and ", HTML("<b>b</b>"), 
          " (green) on the left canvas and watch the relationship trace out on the right plot."),
        checkboxInput("p3_lock_len", "Lock Vector Lengths (||a|| and ||b||)", value = TRUE),
        checkboxInput("p3_show_curve", "Overlay Full Theoretical Curve on Right Plot", value = FALSE),
        hr(),
        h6("Quick Experiments:"),
        actionButton("p3_stretch_a", "Double Length ||a|| (Keep Angle Fixed)", 
                     class = "btn-outline-primary btn-sm w-100 mb-2"),
        actionButton("p3_ortho_btn", "Snap to 90° (Orthogonal)", 
                     class = "btn-outline-secondary btn-sm w-100 mb-2"),
        actionButton("p3_clear_trail", "Reset Vectors & Clear Trace", 
                     class = "btn-outline-danger btn-sm w-100")
      ),
      div(
        div(
          class = "d-flex justify-content-between align-items-center flex-wrap gap-2 mb-2",
          div(id = "p3_status_badge", class = "status-pill status-wait", "Drag vector tips to explore θ and a · b"),
          div(id = "p3_hud", class = "hud-banner mb-0 py-1 px-3", "")
        ),
        layout_columns(
          col_widths = c(6, 6),
          div(
            class = "canvas-wrap",
            tags$canvas(id = "canvas_p3_left", class = "lab-canvas")
          ),
          div(
            class = "canvas-wrap",
            tags$canvas(id = "canvas_p3_right", class = "lab-canvas")
          )
        ),
        div(
          class = "disc-box",
          tags$h6("Group Discussion Prompts (Panel 3)"),
          tags$ol(
            tags$li(tags$b("How Angle Impacts the Sign:"), " With 'Lock Vector Lengths' checked, drag vector ", HTML("<b>a</b>"), " in a full circle around ", HTML("<b>b</b>"), ". For what range of angles ", HTML("&theta;<sub>ab</sub>"), " is ", HTML("<b>a &middot; b</b>"), " positive? Negative? What is the exact angle when ", HTML("<b>a &middot; b</b> = 0"), "?"),
            tags$li(tags$b("Extremes & The Curve Shape:"), " At what angles does the dot product hit its absolute maximum and minimum values, and how do those extreme values relate to the lengths ", HTML("||<b>a</b>||"), " and ", HTML("||<b>b</b>||"), "? Look at the trail of dots you traced on the right plot—what trigonometric function of ", HTML("&theta;<sub>ab</sub>"), " has this exact shape from 0° to 180°?"),
            tags$li(tags$b("Reverse Problem (Dot Product → Angle):"), " Click 'Double Length ||a|| (Keep Angle Fixed)' or uncheck 'Lock Vector Lengths' and stretch ", HTML("<b>a</b>"), " straight outward. Notice that ", HTML("<b>a &middot; b</b>"), " changes even when the angle ", HTML("&theta;<sub>ab</sub>"), " stays the exact same! How must you combine ", HTML("<b>a &middot; b</b>"), ", ", HTML("||<b>a</b>||"), ", and ", HTML("||<b>b</b>||"), " to isolate and solve for the angle ", HTML("&theta;<sub>ab</sub>"), "?")
          ),
          div(class = "stop-banner", "PAUSE HERE: Write down your group's formula connecting a · b, ||a||, ||b||, and θ_ab before moving to Panel 4.")
        )
      )
    )
  ),
  
  # =========================================================================
  # PANEL 4: 3D CROSS PRODUCT LAB
  # =========================================================================
  nav_panel(
    title = "4. 3D Cross Product",
    layout_sidebar(
      sidebar = sidebar(
        width = 330,
        h5("The 3D Cross Product (a × b)"),
        div(
          class = "p-2 mb-2 rounded border bg-light small",
          tags$b("Mouse Controls:"),
          tags$ul(
            class = "mb-0 ps-3 mt-1",
            tags$li(tags$b("Left-click + drag vector tip:"), " Move vector (x, y, z)"),
            tags$li(tags$b("Left-click + drag floor dot:"), " Move (x, y) only"),
            tags$li(tags$b("Right-click + drag:"), " Orbit 3D camera")
          )
        ),
        checkboxInput("p4_tilt_3d", "Allow vectors to tilt off the xy-floor into 3D", value = FALSE),
        checkboxInput("p4_show_perp", "Show 90° Right-Angle Indicators", value = TRUE),
        actionButton("p4_swap_btn", "Swap Vectors a and b", 
                     class = "btn-outline-primary btn-sm w-100 mt-1"),
        actionButton("p4_reset_cam", "Reset Vectors & 3D Camera", 
                     class = "btn-outline-secondary btn-sm w-100 mt-2")
      ),
      div(
        div(
          class = "d-flex justify-content-between align-items-center flex-wrap gap-2 mb-2",
          div(id = "p4_status_badge", class = "status-pill status-match", "90° Orthogonal to both a and b"),
          div(id = "p4_hud", class = "hud-banner mb-0 py-1 px-3", "")
        ),
        div(
          class = "canvas-wrap",
          tags$canvas(id = "canvas_p4", class = "lab-canvas")
        ),
        div(
          class = "disc-box",
          tags$h6("Group Discussion Prompts (Panel 4)"),
          tags$ol(
            tags$li(tags$b("Direction & Orthogonality:"), " With ", HTML("<b>a</b>"), " and ", HTML("<b>b</b>"), " flat on the ", HTML("<i>xy</i>"), "-floor, which axis does ", HTML("<b>a &times; b</b>"), " point along? Now check 'Tilt a and b off the xy-floor' and orbit the 3D view. What remains true about the angle between ", HTML("<b>a &times; b</b>"), " and the original two vectors? How do the live dot products in the banner confirm this?"),
            tags$li(tags$b("Collinear Vectors:"), " Rotate vector ", HTML("<b>a</b>"), " until it points in the exact same direction as ", HTML("<b>b</b>"), " (or exact opposite, 180° apart). What happens to the cross product ", HTML("<b>a &times; b</b>"), " at that moment?"),
            tags$li(tags$b("Order Matters (a × b vs. b × a):"), " Slowly rotate ", HTML("<b>a</b>"), " so it crosses over ", HTML("<b>b</b>"), " to the other side (or click 'Swap Angles of a and b'). What happens to the purple vector ", HTML("<b>a &times; b</b>"), "? Does ", HTML("<b>a &times; b</b> = <b>b &times; a</b>"), "?")
          )
        )
      )
    )
  ),
  
  # =========================================================================
  # EMBEDDED 60-FPS INTERACTIVE CANVAS ENGINE
  # =========================================================================
  tags$script(HTML("
    (function() {
      // 20 deterministic puzzles for Panel 1: [tailX, tailY, dx, dy]
      const P1_PUZZLES = [
        [-4, -2,  3,  2], [ 1, -3, -4,  3], [-5,  1,  5,  2], [ 2,  4, -1, -6],
        [-3,  3,  4, -2], [-2, -4,  2,  5], [ 4, -1, -5, -2], [-1,  2,  4,  3],
        [ 3,  2, -6,  1], [-4,  0,  3, -4], [ 0, -3,  4,  4], [-2,  4,  5, -3],
        [ 4, -3, -3,  5], [-5, -1,  6,  3], [ 2,  1, -4, -4], [-3, -3,  1,  6],
        [ 1,  4,  3, -5], [-4,  2,  5,  1], [ 3, -4, -5,  3], [-1, -2, -3,  4]
      ];

      const P2_PRESETS = {
        '1': { a: [3, 1],  b: [1, 3],  targetLambda: -1.5, v: [2, 1] },
        '2': { a: [4, 2],  b: [-2, 3], targetLambda:  2.0, v: [2, 1] },
        '3': { a: [-3, 2], b: [4, 1],  targetLambda: -2.0, v: [-2, 1] },
        '4': { a: [2, -3], b: [3, 2],  targetLambda:  0.5, v: [4, -2] }
      };

      // Global application state
      const state = {
        p1: {
          puzzle: 1,
          role: 'receiver',
          matchMode: 'exact',
          showCoords: false,
          recTail: [-1, -1],
          recHead: [2, 2],
          dragMode: null,
          dragStartMouse: [0, 0],
          dragStartTail: [0, 0],
          dragStartHead: [0, 0]
        },
        p2: {
          mode: 'scale',
          preset: '1',
          lambda: 1.0,
          targetLambda: -1.5,
          v: [2, 1],
          a: [3, 1],
          b: [1, 3],
          flipB: false,
          posA: [0, 0],
          posB: [0, 0],
          posC: [0, 0],
          dragging: null,
          dragOffset: [0, 0]
        },
        p3: {
          a: [3.0, 3.0],
          b: [4.0, 0.0],
          lockLen: true,
          showCurve: false,
          dragging: null,
          trail: []
        },
        p4: {
          a: [2.8, 1.0, 0.0],
          b: [-1.0, 2.8, 0.0],
          savedZ: [1.5, -1.2],
          tilt3D: false,
          showPerp: true,
          camYaw: -0.65,
          camPitch: 0.48,
          dragging: null,
          lastMouse: [0, 0]
        }
      };

      // Helper: High-DPI canvas setup
      function prepCanvas(canvas) {
        if (!canvas) return null;
        const rect = canvas.getBoundingClientRect();
        if (rect.width === 0 || rect.height === 0) return null;
        const dpr = window.devicePixelRatio || 1;
        if (canvas.width !== Math.round(rect.width * dpr) || canvas.height !== Math.round(rect.height * dpr)) {
          canvas.width = Math.round(rect.width * dpr);
          canvas.height = Math.round(rect.height * dpr);
        }
        const ctx = canvas.getContext('2d');
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        return { ctx, w: rect.width, h: rect.height };
      }

      // Helper: Draw 2D coordinate grid
      
      function getCoords2D(canvas, rangeX, rangeY) {
        const rect = canvas.getBoundingClientRect();
        const w = rect.width, h = rect.height;
        const cx = w / 2, cy = h / 2;
        const scale = Math.min(w / (rangeX * 2), h / (rangeY * 2));
        return {
          cx, cy, scale,
          toScreen: (x, y) => [cx + x * scale, cy - y * scale],
          toWorld: (sx, sy) => [(sx - cx) / scale, (cy - sy) / scale]
        };
      }
      
      function drawGrid2D(ctx, w, h, rangeX, rangeY) {
        ctx.clearRect(0, 0, w, h);
        const cx = w / 2;
        const cy = h / 2;
        const scale = Math.min(w / (rangeX * 2), h / (rangeY * 2));

        const toScreen = (x, y) => [cx + x * scale, cy - y * scale];
        const toWorld = (sx, sy) => [(sx - cx) / scale, (cy - sy) / scale];

        ctx.lineWidth = 1;
        ctx.strokeStyle = '#e2e8f0';
        ctx.fillStyle = '#94a3b8';
        ctx.font = '11px sans-serif';

        for (let x = -Math.floor(rangeX); x <= Math.floor(rangeX); x++) {
          const [sx] = toScreen(x, 0);
          ctx.beginPath();
          ctx.moveTo(sx, 0);
          ctx.lineTo(sx, h);
          ctx.stroke();
          if (x !== 0 && x % 2 === 0) {
            ctx.fillText(x.toString(), sx - 5, cy + 14);
          }
        }
        for (let y = -Math.floor(rangeY); y <= Math.floor(rangeY); y++) {
          const [, sy] = toScreen(0, y);
          ctx.beginPath();
          ctx.moveTo(0, sy);
          ctx.lineTo(w, sy);
          ctx.stroke();
          if (y !== 0 && y % 2 === 0) {
            ctx.fillText(y.toString(), cx + 6, sy + 4);
          }
        }

        // Main Axes
        ctx.strokeStyle = '#64748b';
        ctx.lineWidth = 1.8;
        ctx.beginPath();
        ctx.moveTo(0, cy); ctx.lineTo(w, cy);
        ctx.moveTo(cx, 0); ctx.lineTo(cx, h);
        ctx.stroke();

        ctx.fillStyle = '#334155';
        ctx.font = 'bold 13px sans-serif';
        ctx.fillText('x', w - 16, cy - 8);
        ctx.fillText('y', cx + 10, 16);

        return { cx, cy, scale, toScreen, toWorld };
      }

      // Helper: Draw 2D Arrow
      function drawArrow2D(ctx, x1, y1, x2, y2, color, label, opts = {}) {
        const headLen = opts.headLen || 13;
        const width = opts.width || 3.2;
        const dashed = opts.dashed || false;
        const showHandles = opts.showHandles || false;

        const dx = x2 - x1;
        const dy = y2 - y1;
        const len = Math.hypot(dx, dy);
        const angle = Math.atan2(dy, dx);

        ctx.save();
        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.lineWidth = width;
        if (dashed) ctx.setLineDash([7, 5]);

        ctx.beginPath();
        ctx.moveTo(x1, y1);
        if (len > 4) {
          ctx.lineTo(x2 - Math.cos(angle) * (headLen * 0.7), y2 - Math.sin(angle) * (headLen * 0.7));
        } else {
          ctx.lineTo(x2, y2);
        }
        ctx.stroke();
        ctx.setLineDash([]);

        if (len > 2) {
          ctx.beginPath();
          ctx.moveTo(x2, y2);
          ctx.lineTo(x2 - headLen * Math.cos(angle - Math.PI / 6), y2 - headLen * Math.sin(angle - Math.PI / 6));
          ctx.lineTo(x2 - headLen * Math.cos(angle + Math.PI / 6), y2 - headLen * Math.sin(angle + Math.PI / 6));
          ctx.closePath();
          ctx.fill();
        }

        if (showHandles) {
          ctx.beginPath();
          ctx.arc(x1, y1, 5.5, 0, Math.PI * 2);
          ctx.fillStyle = '#ffffff';
          ctx.fill();
          ctx.lineWidth = 2.5;
          ctx.strokeStyle = color;
          ctx.stroke();
        }

        if (label) {
          const mx = (x1 + x2) / 2;
          const my = (y1 + y2) / 2;
          const nx = -Math.sin(angle) * 16;
          const ny = Math.cos(angle) * 16;
          ctx.font = 'bold 14px sans-serif';
          ctx.fillStyle = color;
          ctx.fillText(label, mx + nx - 10, my + ny + 5);
        }
        ctx.restore();
      }

      // Distance from point P to segment AB
      function distToSegment(px, py, x1, y1, x2, y2) {
        const l2 = (x2 - x1) ** 2 + (y2 - y1) ** 2;
        if (l2 === 0) return Math.hypot(px - x1, py - y1);
        let t = ((px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)) / l2;
        t = Math.max(0, Math.min(1, t));
        return Math.hypot(px - (x1 + t * (x2 - x1)), py - (y1 + t * (y2 - y1)));
      }

      // =====================================================================
      // PANEL 1 RENDER & INTERACTION
      // =====================================================================
      function renderP1() {
        const canvas = document.getElementById('canvas_p1');
        const prep = prepCanvas(canvas);
        if (!prep) return;
        const { ctx, w, h } = prep;
        const g = drawGrid2D(ctx, w, h, 8, 7);

        const p = P1_PUZZLES[state.p1.puzzle - 1];
        const tTail = [p[0], p[1]];
        const tHead = [p[0] + p[2], p[1] + p[3]];
        const tDx = p[2], tDy = p[3];

        const rTail = state.p1.recTail;
        const rHead = state.p1.recHead;
        const rDx = rHead[0] - rTail[0];
        const rDy = rHead[1] - rTail[1];

        const hud = document.getElementById('p1_hud');
        const badge = document.getElementById('p1_status_badge');

        if (state.p1.role === 'sender') {
          const [sx1, sy1] = g.toScreen(tTail[0], tTail[1]);
          const [sx2, sy2] = g.toScreen(tHead[0], tHead[1]);
          drawArrow2D(ctx, sx1, sy1, sx2, sy2, '#7c3aed', 'Target v', { showHandles: true });

          if (state.p1.showCoords) {
            ctx.fillStyle = '#4c1d95';
            ctx.font = 'bold 12px monospace';
            ctx.fillText(`Tail (${tTail[0]}, ${tTail[1]})`, sx1 + 8, sy1 + 16);
            ctx.fillText(`Head (${tHead[0]}, ${tHead[1]})`, sx2 + 8, sy2 - 10);
          }
          const mag = Math.hypot(tDx, tDy).toFixed(2);
          badge.className = 'status-pill status-wait';
          badge.textContent = `Sender View — Describe Puzzle #${state.p1.puzzle} to your group`;
          hud.innerHTML = `<b>Target Vector:</b> Δx = ${tDx}, Δy = ${tDy} &nbsp;|&nbsp; <b>||v||</b> = √(${tDx}² + (${tDy})²) = <b>${mag}</b>`;
        } else {
          // Receiver view
          const exactMatch = (rTail[0] === tTail[0] && rTail[1] === tTail[1] && rHead[0] === tHead[0] && rHead[1] === tHead[1]);
          const vecMatch = (rDx === tDx && rDy === tDy);

          let color = '#2563eb';
          if (state.p1.matchMode === 'exact' && exactMatch) color = '#16a34a';
          if (state.p1.matchMode === 'vector' && vecMatch) color = '#16a34a';

          const [sx1, sy1] = g.toScreen(rTail[0], rTail[1]);
          const [sx2, sy2] = g.toScreen(rHead[0], rHead[1]);
          drawArrow2D(ctx, sx1, sy1, sx2, sy2, color, 'v', { showHandles: true });

          if (state.p1.showCoords) {
            ctx.fillStyle = '#1e293b';
            ctx.font = 'bold 12px monospace';
            ctx.fillText(`Tail (${rTail[0]}, ${rTail[1]})`, sx1 + 8, sy1 + 16);
            ctx.fillText(`Head (${rHead[0]}, ${rHead[1]})`, sx2 + 8, sy2 - 10);
          }

          const mag = Math.hypot(rDx, rDy).toFixed(2);
          hud.innerHTML = `<b>Your Vector:</b> Tail (${rTail[0]}, ${rTail[1]}) → Head (${rHead[0]}, ${rHead[1]}) &nbsp;|&nbsp; <b>v = (${rDx}, ${rDy})</b> &nbsp;|&nbsp; <b>||v|| = ${mag}</b>`;

          if (state.p1.matchMode === 'exact') {
            if (exactMatch) {
              badge.className = 'status-pill status-match';
              badge.textContent = 'Exact Grid Location Matched! Now switch to Round 2 (True Vector Mode).';
            } else if (vecMatch) {
              badge.className = 'status-pill status-partial';
              badge.textContent = 'Same Vector (Δx, Δy match), but at a different starting point!';
            } else {
              badge.className = 'status-pill status-wait';
              badge.textContent = 'Not matched yet — Drag tail (circle), tip (arrowhead), or shaft';
            }
          } else {
            if (vecMatch) {
              badge.className = 'status-pill status-match';
              badge.textContent = `True Vector Matched! v = (${rDx}, ${rDy}) — Try dragging the shaft around the grid!`;
            } else {
              badge.className = 'status-pill status-wait';
              badge.textContent = 'Not matched yet — Match the horizontal and vertical components';
            }
          }
        }
      }

      function setupP1Events() {
        const canvas = document.getElementById('canvas_p1');
        if (!canvas) return;

        canvas.addEventListener('pointerdown', (e) => {
          if (state.p1.role === 'sender') return;
          const g = getCoords2D(canvas, 8, 7);
          const rect = canvas.getBoundingClientRect();
          const mx = e.clientX - rect.left;
          const my = e.clientY - rect.top;

          const [tx, ty] = g.toScreen(state.p1.recTail[0], state.p1.recTail[1]);
          const [hx, hy] = g.toScreen(state.p1.recHead[0], state.p1.recHead[1]);

          if (Math.hypot(mx - hx, my - hy) < 18) {
            state.p1.dragMode = 'head';
          } else if (Math.hypot(mx - tx, my - ty) < 18) {
            state.p1.dragMode = 'tail';
          } else if (distToSegment(mx, my, tx, ty, hx, hy) < 16) {
            state.p1.dragMode = 'body';
            state.p1.dragStartMouse = g.toWorld(mx, my);
            state.p1.dragStartTail = [...state.p1.recTail];
            state.p1.dragStartHead = [...state.p1.recHead];
          }
          if (state.p1.dragMode) {
            canvas.setPointerCapture(e.pointerId);
            renderP1();
          }
        });

        canvas.addEventListener('pointermove', (e) => {
          if (!state.p1.dragMode) return;
          const prep = prepCanvas(canvas);
          if (!prep) return;
          const g = drawGrid2D(prep.ctx, prep.w, prep.h, 8, 7);
          const rect = canvas.getBoundingClientRect();
          const [wx, wy] = g.toWorld(e.clientX - rect.left, e.clientY - rect.top);
          const gx = Math.max(-7, Math.min(7, Math.round(wx)));
          const gy = Math.max(-6, Math.min(6, Math.round(wy)));

          if (state.p1.dragMode === 'head') {
            state.p1.recHead = [gx, gy];
          } else if (state.p1.dragMode === 'tail') {
            state.p1.recTail = [gx, gy];
          } else if (state.p1.dragMode === 'body') {
            const dx = Math.round(wx - state.p1.dragStartMouse[0]);
            const dy = Math.round(wy - state.p1.dragStartMouse[1]);
            state.p1.recTail = [state.p1.dragStartTail[0] + dx, state.p1.dragStartTail[1] + dy];
            state.p1.recHead = [state.p1.dragStartHead[0] + dx, state.p1.dragStartHead[1] + dy];
          }
          renderP1();
        });

        canvas.addEventListener('pointerup', () => {
          state.p1.dragMode = null;
        });
      }

      // =====================================================================
      // PANEL 2 RENDER & INTERACTION
      // =====================================================================
      function renderP2() {
        const canvas = document.getElementById('canvas_p2');
        const prep = prepCanvas(canvas);
        if (!prep) return;
        const { ctx, w, h } = prep;
        const g = drawGrid2D(ctx, w, h, 8, 7);

        const badge = document.getElementById('p2_status_badge');
        const hud = document.getElementById('p2_hud');

        if (state.p2.mode === 'scale') {
          const v = state.p2.v;
          const lam = state.p2.lambda;
          const tLam = state.p2.targetLambda;

          // Dashed line of action
          const [lx1, ly1] = g.toScreen(-v[0] * 4, -v[1] * 4);
          const [lx2, ly2] = g.toScreen(v[0] * 4, v[1] * 4);
          ctx.save();
          ctx.strokeStyle = '#cbd5e1';
          ctx.lineWidth = 2;
          ctx.setLineDash([6, 6]);
          ctx.beginPath();
          ctx.moveTo(lx1, ly1);
          ctx.lineTo(lx2, ly2);
          ctx.stroke();
          ctx.restore();

          const [ox, oy] = g.toScreen(0, 0);
          // Target ghost vector
          const [tx, ty] = g.toScreen(v[0] * tLam, v[1] * tLam);
          drawArrow2D(ctx, ox, oy, tx, ty, '#9333ea', `Target (${tLam}v)`, { dashed: true, width: 2.5 });

          // Base vector v
          const [vx, vy] = g.toScreen(v[0], v[1]);
          drawArrow2D(ctx, ox, oy, vx, vy, '#64748b', 'v', { width: 2.5 });

          // Scaled vector lambda * v
          const [sx, sy] = g.toScreen(v[0] * lam, v[1] * lam);
          drawArrow2D(ctx, ox, oy, sx, sy, '#2563eb', `${lam.toFixed(2)}v`, { width: 4, showHandles: true });

          const matched = Math.abs(lam - tLam) < 0.05;
          badge.className = matched ? 'status-pill status-match' : 'status-pill status-wait';
          badge.textContent = matched 
            ? `Matched Target! λ = ${lam.toFixed(2)}` 
            : `Drag the blue tip of λv to match the purple dashed target (${tLam}v)`;

          const dirText = lam > 0 ? 'Same Direction' : (lam < 0 ? 'Reversed Direction' : 'Zero Vector');
          const scaleText = Math.abs(lam) > 1 ? 'Stretched (|λ| > 1)' : (Math.abs(lam) < 1 ? 'Shrunk (|λ| < 1)' : 'Unchanged Length (|λ| = 1)');
          const lamBox = document.getElementById('p2_lambda_display');
          if (lamBox) lamBox.textContent = `λ = ${lam.toFixed(2)}`;
          hud.innerHTML = `<b>v = (${v[0]}, ${v[1]})</b> &nbsp;|&nbsp; <b>λv = (${(v[0]*lam).toFixed(1)}, ${(v[1]*lam).toFixed(1)})</b> &nbsp;|&nbsp; ${dirText}, ${scaleText}`;
          return;
        }

        // Addition or Subtraction
        const a = state.p2.a;
        const bRaw = state.p2.b;
        const bVec = state.p2.flipB ? [-bRaw[0], -bRaw[1]] : bRaw;
        const bLabel = state.p2.flipB ? '-b' : 'b';
        const cVec = state.p2.mode === 'add' 
          ? [a[0] + bRaw[0], a[1] + bRaw[1]] 
          : [a[0] - bRaw[0], a[1] - bRaw[1]];
        const cLabel = state.p2.mode === 'add' ? 'a + b' : 'a - b';

        const pA = state.p2.posA;
        const pB = state.p2.posB;
        const pC = state.p2.posC;

        // Draw Resultant c (purple)
        const [cx1, cy1] = g.toScreen(pC[0], pC[1]);
        const [cx2, cy2] = g.toScreen(pC[0] + cVec[0], pC[1] + cVec[1]);
        drawArrow2D(ctx, cx1, cy1, cx2, cy2, '#7c3aed', cLabel, { width: 3.8, showHandles: true });

        // Draw Vector a (blue)
        const [ax1, ay1] = g.toScreen(pA[0], pA[1]);
        const [ax2, ay2] = g.toScreen(pA[0] + a[0], pA[1] + a[1]);
        drawArrow2D(ctx, ax1, ay1, ax2, ay2, '#2563eb', 'a', { width: 3.4, showHandles: true });

        // Draw Vector b or -b (green)
        const [bx1, by1] = g.toScreen(pB[0], pB[1]);
        const [bx2, by2] = g.toScreen(pB[0] + bVec[0], pB[1] + bVec[1]);
        drawArrow2D(ctx, bx1, by1, bx2, by2, '#16a34a', bLabel, { width: 3.4, showHandles: true });

        // Check geometric triangle completion
        const near = (u, v) => Math.hypot(u[0] - v[0], u[1] - v[1]) < 0.25;
        const headA = [pA[0] + a[0], pA[1] + a[1]];
        const headB = [pB[0] + bVec[0], pB[1] + bVec[1]];
        const headC = [pC[0] + cVec[0], pC[1] + cVec[1]];

        let statusMsg = 'Drag the body of any vector to connect them into a closed triangle';
        let isMatch = false;

        if (state.p2.mode === 'add' && !state.p2.flipB) {
          if (near(pB, headA) && near(pC, pA) && near(headC, headB)) {
            isMatch = true;
            statusMsg = 'Head-to-Tail Triangle Formed! (Walk along a, then along b = a + b)';
          } else if (near(pA, headB) && near(pC, pB) && near(headC, headA)) {
            isMatch = true;
            statusMsg = 'Head-to-Tail Triangle Formed! (Walk along b, then along a = b + a)';
          }
        } else if (state.p2.mode === 'sub') {
          if (state.p2.flipB && near(pB, headA) && near(pC, pA) && near(headC, headB)) {
            isMatch = true;
            statusMsg = 'Head-to-Tail Subtraction! a + (-b) = a - b';
          } else if (!state.p2.flipB && near(pA, pB) && near(pC, headB) && near(headC, headA)) {
            isMatch = true;
            statusMsg = 'Tip-to-Tip Triangle! a - b connects the tip of b to the tip of a';
          }
        }

        badge.className = isMatch ? 'status-pill status-match' : 'status-pill status-wait';
        badge.textContent = statusMsg;
        hud.innerHTML = `<b>a = (${a[0]}, ${a[1]})</b> &nbsp;|&nbsp; <b>${bLabel} = (${bVec[0]}, ${bVec[1]})</b> &nbsp;|&nbsp; <b>${cLabel} = (${cVec[0]}, ${cVec[1]})</b>`;
      }

      function setupP2Events() {
        const canvas = document.getElementById('canvas_p2');
        if (!canvas) return;

        canvas.addEventListener('pointerdown', (e) => {
          const g = getCoords2D(canvas, 8, 7);
          const rect = canvas.getBoundingClientRect();
          const mx = e.clientX - rect.left;
          const my = e.clientY - rect.top;
          const [wx, wy] = g.toWorld(mx, my);

          if (state.p2.mode === 'scale') {
            state.p2.dragging = 'scale_tip';
            canvas.setPointerCapture(e.pointerId);
            return;
          }

          const a = state.p2.a;
          const bRaw = state.p2.b;
          const bVec = state.p2.flipB ? [-bRaw[0], -bRaw[1]] : bRaw;
          const cVec = state.p2.mode === 'add' 
            ? [a[0] + bRaw[0], a[1] + bRaw[1]] 
            : [a[0] - bRaw[0], a[1] - bRaw[1]];

          const [bx1, by1] = g.toScreen(state.p2.posB[0], state.p2.posB[1]);
          const [bx2, by2] = g.toScreen(state.p2.posB[0] + bVec[0], state.p2.posB[1] + bVec[1]);
          const [ax1, ay1] = g.toScreen(state.p2.posA[0], state.p2.posA[1]);
          const [ax2, ay2] = g.toScreen(state.p2.posA[0] + a[0], state.p2.posA[1] + a[1]);
          const [cx1, cy1] = g.toScreen(state.p2.posC[0], state.p2.posC[1]);
          const [cx2, cy2] = g.toScreen(state.p2.posC[0] + cVec[0], state.p2.posC[1] + cVec[1]);

          if (distToSegment(mx, my, bx1, by1, bx2, by2) < 16) {
            state.p2.dragging = 'b';
            state.p2.dragOffset = [wx - state.p2.posB[0], wy - state.p2.posB[1]];
          } else if (distToSegment(mx, my, ax1, ay1, ax2, ay2) < 16) {
            state.p2.dragging = 'a';
            state.p2.dragOffset = [wx - state.p2.posA[0], wy - state.p2.posA[1]];
          } else if (distToSegment(mx, my, cx1, cy1, cx2, cy2) < 16) {
            state.p2.dragging = 'c';
            state.p2.dragOffset = [wx - state.p2.posC[0], wy - state.p2.posC[1]];
          }

          if (state.p2.dragging) {
            canvas.setPointerCapture(e.pointerId);
          }
        });

        canvas.addEventListener('pointermove', (e) => {
          if (!state.p2.dragging) return;
          const prep = prepCanvas(canvas);
          if (!prep) return;
          const g = drawGrid2D(prep.ctx, prep.w, prep.h, 8, 7);
          const rect = canvas.getBoundingClientRect();
          const [wx, wy] = g.toWorld(e.clientX - rect.left, e.clientY - rect.top);

          if (state.p2.dragging === 'scale_tip') {
            const v = state.p2.v;
            const dot = wx * v[0] + wy * v[1];
            const v2 = v[0] * v[0] + v[1] * v[1];
            // Snap smoothly to 0.05 increments (and magnet-snap to targetLambda)
            let lam = Math.round((dot / v2) * 20) / 20;
            if (Math.abs(lam - state.p2.targetLambda) < 0.08) {
              lam = state.p2.targetLambda;
            }
            lam = Math.max(-2.5, Math.min(2.5, lam));
            state.p2.lambda = lam;
            renderP2();
            return;
          }

          let nx = wx - state.p2.dragOffset[0];
          let ny = wy - state.p2.dragOffset[1];
          // Snap to 0.5 grid or integer points
          nx = Math.round(nx * 2) / 2;
          ny = Math.round(ny * 2) / 2;
          if (Math.abs(nx - Math.round(nx)) < 0.35) nx = Math.round(nx);
          if (Math.abs(ny - Math.round(ny)) < 0.35) ny = Math.round(ny);

          if (state.p2.dragging === 'a') state.p2.posA = [nx, ny];
          if (state.p2.dragging === 'b') state.p2.posB = [nx, ny];
          if (state.p2.dragging === 'c') state.p2.posC = [nx, ny];
          renderP2();
        });

        canvas.addEventListener('pointerup', () => {
          state.p2.dragging = null;
        });
      }

      // =====================================================================
      // PANEL 3 RENDER & INTERACTION (ANGLE <-> DOT PRODUCT, NO PROJECTIONS)
      // =====================================================================
      function recordP3Trail() {
        const a = state.p3.a;
        const b = state.p3.b;
        const magA = Math.hypot(a[0], a[1]);
        const magB = Math.hypot(b[0], b[1]);
        if (magA < 0.01 || magB < 0.01) return;
        const dot = a[0] * b[0] + a[1] * b[1];
        const cosT = Math.max(-1, Math.min(1, dot / (magA * magB)));
        const deg = Math.acos(cosT) * 180 / Math.PI;
        state.p3.trail.push({ deg, dot });
        if (state.p3.trail.length > 220) state.p3.trail.shift();
      }

      function renderP3() {
        const cLeft = document.getElementById('canvas_p3_left');
        const cRight = document.getElementById('canvas_p3_right');
        const pL = prepCanvas(cLeft);
        const pR = prepCanvas(cRight);
        if (!pL || !pR) return;

        const a = state.p3.a;
        const b = state.p3.b;
        const magA = Math.hypot(a[0], a[1]);
        const magB = Math.hypot(b[0], b[1]);
        const dot = a[0] * b[0] + a[1] * b[1];
        const cosTheta = (magA > 0 && magB > 0) ? Math.max(-1, Math.min(1, dot / (magA * magB))) : 1;
        const thetaDeg = Math.acos(cosTheta) * 180 / Math.PI;

        // --- Left Canvas: Vector Canvas ---
        const g = drawGrid2D(pL.ctx, pL.w, pL.h, 6.5, 6.5);
        const [ox, oy] = g.toScreen(0, 0);

        // Optional locked length orbit circle for a
        if (state.p3.lockLen) {
          pL.ctx.save();
          pL.ctx.strokeStyle = '#dbeafe';
          pL.ctx.lineWidth = 1.5;
          pL.ctx.setLineDash([4, 4]);
          pL.ctx.beginPath();
          pL.ctx.arc(ox, oy, magA * g.scale, 0, Math.PI * 2);
          pL.ctx.stroke();
          pL.ctx.restore();
        }

        // Draw shaded angle sector between a and b
        const angA = Math.atan2(-a[1], a[0]); // screen canvas angle
        const angB = Math.atan2(-b[1], b[0]);
        let diff = angA - angB;
        while (diff > Math.PI) diff -= Math.PI * 2;
        while (diff < -Math.PI) diff += Math.PI * 2;

        pL.ctx.save();
        pL.ctx.beginPath();
        pL.ctx.moveTo(ox, oy);
        pL.ctx.arc(ox, oy, 42, angB, angB + diff, diff < 0);
        pL.ctx.closePath();
        pL.ctx.fillStyle = dot > 0.05 ? 'rgba(22, 163, 74, 0.18)' : (dot < -0.05 ? 'rgba(220, 38, 38, 0.18)' : 'rgba(234, 179, 8, 0.28)');
        pL.ctx.fill();
        pL.ctx.strokeStyle = '#475569';
        pL.ctx.lineWidth = 1.5;
        pL.ctx.stroke();

        const midAng = angB + diff / 2;
        pL.ctx.fillStyle = '#0f172a';
        pL.ctx.font = 'bold 13px sans-serif';
        pL.ctx.fillText(`θ = ${thetaDeg.toFixed(1)}°`, ox + Math.cos(midAng) * 58 - 24, oy + Math.sin(midAng) * 58 + 4);
        pL.ctx.restore();

        const [bx, by] = g.toScreen(b[0], b[1]);
        const [ax, ay] = g.toScreen(a[0], a[1]);
        drawArrow2D(pL.ctx, ox, oy, bx, by, '#16a34a', 'b', { width: 3.5, showHandles: true });
        drawArrow2D(pL.ctx, ox, oy, ax, ay, '#2563eb', 'a', { width: 3.5, showHandles: true });

        // --- Right Canvas: Angle vs Dot Product Plot ---
        const ctxR = pR.ctx;
        const wR = pR.w, hR = pR.h;
        ctxR.clearRect(0, 0, wR, hR);

        const padL = 52, padR = 24, padT = 30, padB = 42;
        const plotW = wR - padL - padR;
        const plotH = hR - padT - padB;
        const maxDot = Math.max(20, Math.ceil(magA * magB * 1.15));
        const midY = padT + plotH / 2;

        const mapX = (deg) => padL + (deg / 180) * plotW;
        const mapY = (d) => midY - (d / maxDot) * (plotH / 2);

        // Gridlines on Right Plot
        ctxR.strokeStyle = '#e2e8f0';
        ctxR.lineWidth = 1;
        [0, 45, 90, 135, 180].forEach(deg => {
          const x = mapX(deg);
          ctxR.beginPath(); ctxR.moveTo(x, padT); ctxR.lineTo(x, padT + plotH); ctxR.stroke();
          ctxR.fillStyle = '#475569';
          ctxR.font = '11px sans-serif';
          ctxR.fillText(`${deg}°`, x - 10, padT + plotH + 18);
        });

        [-maxDot, -maxDot/2, 0, maxDot/2, maxDot].forEach(val => {
          const y = mapY(val);
          ctxR.beginPath(); ctxR.moveTo(padL, y); ctxR.lineTo(padL + plotW, y); ctxR.stroke();
          ctxR.fillStyle = '#475569';
          ctxR.font = '11px sans-serif';
          ctxR.fillText(val.toFixed(0), 12, y + 4);
        });

        // Zero horizontal axis
        ctxR.strokeStyle = '#64748b';
        ctxR.lineWidth = 1.6;
        ctxR.beginPath();
        ctxR.moveTo(padL, midY); ctxR.lineTo(padL + plotW, midY);
        ctxR.moveTo(padL, padT); ctxR.lineTo(padL, padT + plotH);
        ctxR.stroke();

        ctxR.fillStyle = '#0f172a';
        ctxR.font = 'bold 12px sans-serif';
        ctxR.fillText('Angle θ_ab (degrees)', padL + plotW / 2 - 55, hR - 8);
        ctxR.fillText('Dot Product (a · b)', padL + 8, 18);

        // Optional theoretical cosine curve
        if (state.p3.showCurve) {
          ctxR.save();
          ctxR.strokeStyle = '#94a3b8';
          ctxR.lineWidth = 2;
          ctxR.setLineDash([5, 5]);
          ctxR.beginPath();
          for (let d = 0; d <= 180; d += 2) {
            const val = magA * magB * Math.cos(d * Math.PI / 180);
            if (d === 0) ctxR.moveTo(mapX(d), mapY(val));
            else ctxR.lineTo(mapX(d), mapY(val));
          }
          ctxR.stroke();
          ctxR.restore();
        }

        // Explored trail dots
        state.p3.trail.forEach(pt => {
          ctxR.beginPath();
          ctxR.arc(mapX(pt.deg), mapY(pt.dot), 3.5, 0, Math.PI * 2);
          ctxR.fillStyle = 'rgba(37, 99, 235, 0.35)';
          ctxR.fill();
        });

        // Current active point
        const curX = mapX(thetaDeg);
        const curY = mapY(dot);
        ctxR.beginPath();
        ctxR.arc(curX, curY, 7, 0, Math.PI * 2);
        ctxR.fillStyle = '#ef4444';
        ctxR.fill();
        ctxR.lineWidth = 2;
        ctxR.strokeStyle = '#ffffff';
        ctxR.stroke();
        
        // Update Live Status Pill
        const badge = document.getElementById('p3_status_badge');
        if (Math.abs(dot) < 0.15) {
          badge.className = 'status-pill status-match';
          badge.textContent = 'Orthogonal (θ = 90°) — Dot Product is 0!';
        } else if (thetaDeg < 1.5) {
          badge.className = 'status-pill status-match';
          badge.textContent = 'Same Direction (θ = 0°) — Maximum Positive Dot Product!';
        } else if (thetaDeg > 178.5) {
          badge.className = 'status-pill status-partial';
          badge.textContent = 'Opposite Direction (θ = 180°) — Minimum Negative Dot Product!';
        } else if (dot > 0) {
          badge.className = 'status-pill status-wait';
          badge.textContent = `Acute Angle (θ = ${thetaDeg.toFixed(1)} < 90°) — Positive Dot Product`;
        } else {
          badge.className = 'status-pill status-wait';
          badge.textContent = `Obtuse Angle (θ = ${thetaDeg.toFixed(1)} > 90°) — Negative Dot Product`;
        }

        // Update Live Equation Banner
        const hud = document.getElementById('p3_hud');
        hud.innerHTML = 
          `<b>a</b> = (${a[0].toFixed(1)}, ${a[1].toFixed(1)}), <b>||a||</b> = ${magA.toFixed(2)} &nbsp;|&nbsp; ` +
          `<b>b</b> = (${b[0].toFixed(1)}, ${b[1].toFixed(1)}), <b>||b||</b> = ${magB.toFixed(2)} &nbsp;|&nbsp; ` +
          `<b>a · b</b> = (${a[0].toFixed(1)})(${b[0].toFixed(1)}) + (${a[1].toFixed(1)})(${b[1].toFixed(1)}) = <span class='math-badge'>${dot.toFixed(2)}</span> &nbsp;|&nbsp`;
      }

      function setupP3Events() {
        const canvas = document.getElementById('canvas_p3_left');
        if (!canvas) return;

        canvas.addEventListener('pointerdown', (e) => {
          const prep = prepCanvas(canvas);
          if (!prep) return;
          const g = getCoords2D(canvas, 6.5, 6.5);
          const rect = canvas.getBoundingClientRect();
          const mx = e.clientX - rect.left;
          const my = e.clientY - rect.top;

          const [ax, ay] = g.toScreen(state.p3.a[0], state.p3.a[1]);
          const [bx, by] = g.toScreen(state.p3.b[0], state.p3.b[1]);

          if (Math.hypot(mx - ax, my - ay) < 22) {
            state.p3.dragging = 'a';
          } else if (Math.hypot(mx - bx, my - by) < 22) {
            state.p3.dragging = 'b';
          }
          if (state.p3.dragging) {
            canvas.setPointerCapture(e.pointerId);
          }
        });

        canvas.addEventListener('pointermove', (e) => {
          if (!state.p3.dragging) return;
          const prep = prepCanvas(canvas);
          if (!prep) return;
          const g = drawGrid2D(prep.ctx, prep.w, prep.h, 6.5, 6.5);
          const rect = canvas.getBoundingClientRect();
          let [wx, wy] = g.toWorld(e.clientX - rect.left, e.clientY - rect.top);

          const vec = state.p3.dragging === 'a' ? state.p3.a : state.p3.b;
          const curLen = Math.hypot(vec[0], vec[1]) || 4.0;

          if (state.p3.lockLen) {
            const ang = Math.atan2(wy, wx);
            wx = curLen * Math.cos(ang);
            wy = curLen * Math.sin(ang);
          } else {
            wx = Math.max(-6, Math.min(6, Math.round(wx * 2) / 2));
            wy = Math.max(-6, Math.min(6, Math.round(wy * 2) / 2));
          }

          if (state.p3.dragging === 'a') state.p3.a = [wx, wy];
          else state.p3.b = [wx, wy];

          recordP3Trail();
          renderP3();
        });

        canvas.addEventListener('pointerup', () => {
          state.p3.dragging = null;
        });
      }

      // =====================================================================
      // PANEL 4 RENDER & INTERACTION (3D CROSS PRODUCT)
      // =====================================================================
      function project3D(x, y, z, w, h, yaw, pitch) {
        // Right-handed coordinate system: Z is up
        const x1 = x * Math.cos(yaw) - y * Math.sin(yaw);
        const y1 = x * Math.sin(yaw) + y * Math.cos(yaw);
        const z2 = z * Math.cos(pitch) - y1 * Math.sin(pitch);
        const depth = z * Math.sin(pitch) + y1 * Math.cos(pitch);
        const scale = Math.min(w, h) / 13.5;
        return [w / 2 + x1 * scale, h / 2 - z2 * scale, depth];
      }

      // Unproject screen (mx, my) onto a horizontal plane at height z = zPlane
      function screenToPlaneXY(mx, my, zPlane, w, h, yaw, pitch) {
        const scale = Math.min(w, h) / 13.5;
        const x1 = (mx - w / 2) / scale;
        const z2 = (h / 2 - my) / scale;
        const sinP = Math.sin(pitch);
        const cosP = Math.cos(pitch);
        // Guard against shallow camera pitch
        const y1 = Math.abs(sinP) > 0.12 ? (zPlane * cosP - z2) / sinP : 0;
        const x = x1 * Math.cos(yaw) + y1 * Math.sin(yaw);
        const y = -x1 * Math.sin(yaw) + y1 * Math.cos(yaw);
        return [
          Math.max(-4, Math.min(4, x)),
          Math.max(-4, Math.min(4, y))
        ];
      }

      function renderP4() {
        const canvas = document.getElementById('canvas_p4');
        const prep = prepCanvas(canvas);
        if (!prep) return;
        const { ctx, w, h } = prep;
        ctx.clearRect(0, 0, w, h);

        const yaw = state.p4.camYaw;
        const pitch = state.p4.camPitch;
        const proj = (x, y, z) => project3D(x, y, z, w, h, yaw, pitch);

        // Draw xy-floor grid
        ctx.lineWidth = 1;
        ctx.strokeStyle = '#e2e8f0';
        for (let i = -4; i <= 4; i++) {
          const p1 = proj(i, -4, 0), p2 = proj(i, 4, 0);
          ctx.beginPath(); ctx.moveTo(p1[0], p1[1]); ctx.lineTo(p2[0], p2[1]); ctx.stroke();
          const p3 = proj(-4, i, 0), p4 = proj(4, i, 0);
          ctx.beginPath(); ctx.moveTo(p3[0], p3[1]); ctx.lineTo(p4[0], p4[1]); ctx.stroke();
        }

        // Draw 3D coordinate axes
        const origin = proj(0, 0, 0);
        const axes = [
          { end: [4.8, 0, 0], label: '+x', color: '#64748b' },
          { end: [0, 4.8, 0], label: '+y', color: '#64748b' },
          { end: [0, 0, 4.8], label: '+z', color: '#64748b' }
        ];
        axes.forEach(ax => {
          const neg = proj(-ax.end[0], -ax.end[1], -ax.end[2]);
          const pos = proj(ax.end[0], ax.end[1], ax.end[2]);
          ctx.strokeStyle = '#cbd5e1';
          ctx.lineWidth = 1.5;
          ctx.beginPath(); ctx.moveTo(neg[0], neg[1]); ctx.lineTo(origin[0], origin[1]); ctx.stroke();
          drawArrow2D(ctx, origin[0], origin[1], pos[0], pos[1], ax.color, ax.label, { width: 2, headLen: 9 });
        });

        const a = [state.p4.a[0], state.p4.a[1], state.p4.tilt3D ? state.p4.a[2] : 0];
        const b = [state.p4.b[0], state.p4.b[1], state.p4.tilt3D ? state.p4.b[2] : 0];
        const c = [
          a[1] * b[2] - a[2] * b[1],
          a[2] * b[0] - a[0] * b[2],
          a[0] * b[1] - a[1] * b[0]
        ];
        const cVis = [c[0] * 0.45, c[1] * 0.45, c[2] * 0.45];

        const pO = proj(0, 0, 0);
        const pA = proj(a[0], a[1], a[2]);
        const pB = proj(b[0], b[1], b[2]);
        const pAB = proj(a[0] + b[0], a[1] + b[1], a[2] + b[2]);

        // Shaded parallelogram spanned by a and b
        ctx.save();
        ctx.fillStyle = 'rgba(124, 58, 237, 0.12)';
        ctx.strokeStyle = 'rgba(124, 58, 237, 0.35)';
        ctx.setLineDash([4, 4]);
        ctx.beginPath();
        ctx.moveTo(pO[0], pO[1]);
        ctx.lineTo(pA[0], pA[1]);
        ctx.lineTo(pAB[0], pAB[1]);
        ctx.lineTo(pB[0], pB[1]);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
        ctx.restore();

        // If 3D tilt is enabled, draw vertical drop-lines and xy-floor shadow handles
        if (state.p4.tilt3D) {
          const drawShadowStem = (vec, pTip, color) => {
            const pFloor = proj(vec[0], vec[1], 0);
            ctx.save();
            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.setLineDash([4, 4]);
            ctx.beginPath();
            ctx.moveTo(pFloor[0], pFloor[1]);
            ctx.lineTo(pTip[0], pTip[1]);
            ctx.stroke();
            ctx.setLineDash([]);
            ctx.beginPath();
            ctx.arc(pFloor[0], pFloor[1], 5.5, 0, Math.PI * 2);
            ctx.fillStyle = '#ffffff';
            ctx.fill();
            ctx.lineWidth = 2;
            ctx.stroke();
            ctx.restore();
          };
          drawShadowStem(a, pA, '#2563eb');
          drawShadowStem(b, pB, '#16a34a');
        }

        // 90-degree right-angle markers
        const cNorm = Math.hypot(c[0], c[1], c[2]);
        const aNorm = Math.hypot(a[0], a[1], a[2]);
        const bNorm = Math.hypot(b[0], b[1], b[2]);
        if (state.p4.showPerp && cNorm > 0.25 && aNorm > 0.1 && bNorm > 0.1) {
          const uC = [c[0] / cNorm * 0.65, c[1] / cNorm * 0.65, c[2] / cNorm * 0.65];
          const uA = [a[0] / aNorm * 0.65, a[1] / aNorm * 0.65, a[2] / aNorm * 0.65];
          const uB = [b[0] / bNorm * 0.65, b[1] / bNorm * 0.65, b[2] / bNorm * 0.65];

          const drawRightAngle3D = (uVec, color) => {
            const s1 = proj(uVec[0], uVec[1], uVec[2]);
            const s2 = proj(uVec[0] + uC[0], uVec[1] + uC[1], uVec[2] + uC[2]);
            const s3 = proj(uC[0], uC[1], uC[2]);
            ctx.save();
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(s1[0], s1[1]);
            ctx.lineTo(s2[0], s2[1]);
            ctx.lineTo(s3[0], s3[1]);
            ctx.stroke();
            ctx.restore();
          };
          drawRightAngle3D(uA, '#2563eb');
          drawRightAngle3D(uB, '#16a34a');
        }

        // Draw vectors a, b, and a x b (with grab circles on tips of a and b)
        drawArrow2D(ctx, pO[0], pO[1], pA[0], pA[1], '#2563eb', 'a', { width: 3.6 });
        drawArrow2D(ctx, pO[0], pO[1], pB[0], pB[1], '#16a34a', 'b', { width: 3.6 });
        const pC = proj(cVis[0], cVis[1], cVis[2]);
        drawArrow2D(ctx, pO[0], pO[1], pC[0], pC[1], '#7c3aed', 'a × b', { width: 4.2 });

        // Tip grab-rings for a and b
        [[pA, '#2563eb'], [pB, '#16a34a']].forEach(([pt, col]) => {
          ctx.beginPath();
          ctx.arc(pt[0], pt[1], 6, 0, Math.PI * 2);
          ctx.fillStyle = col;
          ctx.fill();
          ctx.lineWidth = 2;
          ctx.strokeStyle = '#ffffff';
          ctx.stroke();
        });

        const dotCA = (c[0]*a[0] + c[1]*a[1] + c[2]*a[2]).toFixed(1);
        const dotCB = (c[0]*b[0] + c[1]*b[1] + c[2]*b[2]).toFixed(1);

        const badge = document.getElementById('p4_status_badge');
        if (cNorm < 0.2) {
          badge.className = 'status-pill status-partial';
          badge.textContent = 'a and b are Collinear (0° or 180°) → Cross Product is (0, 0, 0)!';
        } else {
          badge.className = 'status-pill status-match';
          const dirHint = !state.p4.tilt3D 
            ? (c[2] > 0 ? 'Points Straight UP (+z)' : 'Points Straight DOWN (-z)') 
            : '90° Orthogonal to both a and b';
          badge.textContent = `a × b = (${c[0].toFixed(1)}, ${c[1].toFixed(1)}, ${c[2].toFixed(1)}) — ${dirHint}`;
        }

        const hud = document.getElementById('p4_hud');
        hud.innerHTML = 
          `<b>a</b> = (${a[0].toFixed(1)}, ${a[1].toFixed(1)}, ${a[2].toFixed(1)}) &nbsp;|&nbsp; ` +
          `<b>b</b> = (${b[0].toFixed(1)}, ${b[1].toFixed(1)}, ${b[2].toFixed(1)}) &nbsp;|&nbsp; ` +
          `<b>(a × b) · a</b> = ${dotCA} (90°) &nbsp;|&nbsp; <b>(a × b) · b</b> = ${dotCB} (90°)`;
      }

      function setupP4Events() {
        const canvas = document.getElementById('canvas_p4');
        if (!canvas) return;

        // Disable browser right-click menu on the 3D canvas so right-drag orbits cleanly
        canvas.addEventListener('contextmenu', (e) => e.preventDefault());

        canvas.addEventListener('pointerdown', (e) => {
          const rect = canvas.getBoundingClientRect();
          const mx = e.clientX - rect.left;
          const my = e.clientY - rect.top;
          const w = rect.width, h = rect.height;
          state.p4.lastMouse = [mx, my];

          // Right-click (button === 2) always orbits the 3D frame
          if (e.button === 2) {
            state.p4.dragging = 'orbit';
            canvas.setPointerCapture(e.pointerId);
            return;
          }

          // Left-click (button === 0): check vector tips and floor shadow handles
          const yaw = state.p4.camYaw, pitch = state.p4.camPitch;
          const a = [state.p4.a[0], state.p4.a[1], state.p4.tilt3D ? state.p4.a[2] : 0];
          const b = [state.p4.b[0], state.p4.b[1], state.p4.tilt3D ? state.p4.b[2] : 0];

          const pA = project3D(a[0], a[1], a[2], w, h, yaw, pitch);
          const pB = project3D(b[0], b[1], b[2], w, h, yaw, pitch);
          const pAFloor = project3D(a[0], a[1], 0, w, h, yaw, pitch);
          const pBFloor = project3D(b[0], b[1], 0, w, h, yaw, pitch);

          if (state.p4.tilt3D && Math.hypot(mx - pAFloor[0], my - pAFloor[1]) < 24) {
            state.p4.dragging = 'floor_a';
          } else if (state.p4.tilt3D && Math.hypot(mx - pBFloor[0], my - pBFloor[1]) < 24) {
            state.p4.dragging = 'floor_b';
          } else if (Math.hypot(mx - pA[0], my - pA[1]) < 22) {
            state.p4.dragging = 'tip_a';
          } else if (Math.hypot(mx - pB[0], my - pB[1]) < 22) {
            state.p4.dragging = 'tip_b';
          } else {
            state.p4.dragging = 'orbit';
          }
          canvas.setPointerCapture(e.pointerId);
        });

        canvas.addEventListener('pointermove', (e) => {
          if (!state.p4.dragging) return;
          const rect = canvas.getBoundingClientRect();
          const mx = e.clientX - rect.left;
          const my = e.clientY - rect.top;
          const w = rect.width, h = rect.height;
          const dx = mx - state.p4.lastMouse[0];
          const dy = my - state.p4.lastMouse[1];
          state.p4.lastMouse = [mx, my];

          if (state.p4.dragging === 'orbit') {
            state.p4.camYaw -= dx * 0.01;
            state.p4.camPitch = Math.max(0.18, Math.min(1.45, state.p4.camPitch + dy * 0.01));
            renderP4();
            return;
          }

          const yaw = state.p4.camYaw, pitch = state.p4.camPitch;
          const scale = Math.min(w, h) / 13.5;
          const target = (state.p4.dragging.endsWith('_a')) ? state.p4.a : state.p4.b;

          if (!state.p4.tilt3D || state.p4.dragging.startsWith('floor_')) {
            // Always unproject onto the xy-floor (z = 0) so the floor dot tracks the cursor 1:1
            const [nx, ny] = screenToPlaneXY(mx, my, 0, w, h, yaw, pitch);
            target[0] = Math.round(nx * 4) / 4;
            target[1] = Math.round(ny * 4) / 4;
          } else if (state.p4.dragging.startsWith('tip_')) {
            // In 3D mode, dragging the vector tip smoothly raises/lowers its z-height
            const dz = -dy / (scale * Math.max(0.3, Math.cos(pitch)));
            target[2] = Math.max(-3.5, Math.min(3.5, Math.round((target[2] + dz) * 10) / 10));
          }
          renderP4();
        });

        canvas.addEventListener('pointerup', () => {
          state.p4.dragging = null;
        });
      }

      // Render all visible canvases
      function renderAll() {
        renderP1();
        renderP2();
        renderP3();
        renderP4();
      }

      // Listen to custom messages from Shiny server
      if (window.Shiny) {
        Shiny.addCustomMessageHandler('syncLabState', function(msg) {
          if (msg.panel === 'p1') {
            if (msg.data.action === 'snap_origin') {
              const dx = state.p1.recHead[0] - state.p1.recTail[0];
              const dy = state.p1.recHead[1] - state.p1.recTail[1];
              state.p1.recTail = [0, 0];
              state.p1.recHead = [dx, dy];
            } else {
              Object.assign(state.p1, msg.data);
            }
            renderP1();
          } else if (msg.panel === 'p2') {
            if (msg.data.preset && msg.data.preset !== state.p2.preset) {
              const pr = P2_PRESETS[msg.data.preset];
              state.p2.a = [...pr.a];
              state.p2.b = [...pr.b];
              state.p2.v = [...pr.v];
              state.p2.targetLambda = pr.targetLambda;
              state.p2.posA = [0, 0];
              state.p2.posB = [0, 0];
              state.p2.posC = [0, 0];
            }
            Object.assign(state.p2, msg.data);
            renderP2();
          } else if (msg.panel === 'p3') {
            if (msg.data.action === 'stretch_a') {
              state.p3.a = [state.p3.a[0] * 1.5, state.p3.a[1] * 1.5];
              recordP3Trail();
            } else if (msg.data.action === 'ortho') {
              const lenA = Math.hypot(state.p3.a[0], state.p3.a[1]) || 4;
              const angB = Math.atan2(state.p3.b[1], state.p3.b[0]);
              state.p3.a = [lenA * Math.cos(angB + Math.PI / 2), lenA * Math.sin(angB + Math.PI / 2)];
              recordP3Trail();
            } else if (msg.data.action === 'clear') {
              state.p3.a = [3.0, 3.0];
              state.p3.b = [4.0, 0.0];
              state.p3.trail = [];
              recordP3Trail();
            } else {
              Object.assign(state.p3, msg.data);
            }
            renderP3();
          } else if (msg.panel === 'p4') {
            if (msg.data.action === 'swap') {
              const tmp = [...state.p4.a];
              state.p4.a = [...state.p4.b];
              state.p4.b = tmp;
            } else if (msg.data.action === 'reset') {
              state.p4.a = [2.8, 1.0, state.p4.tilt3D ? 1.5 : 0.0];
              state.p4.b = [-1.0, 2.8, state.p4.tilt3D ? -1.2 : 0.0];
              state.p4.camYaw = -0.65;
              state.p4.camPitch = 0.48;
            } else {
              if (msg.data.tilt3D === true && !state.p4.tilt3D) {
                // Give a and b non-zero z heights immediately when checking 3D tilt
                if (state.p4.a[2] === 0 && state.p4.b[2] === 0) {
                  state.p4.a[2] = 1.5;
                  state.p4.b[2] = -1.2;
                }
              }
              Object.assign(state.p4, msg.data);
            }
            renderP4();
          }
        });
      }

      document.addEventListener('DOMContentLoaded', () => {
        setupP1Events();
        setupP2Events();
        setupP3Events();
        setupP4Events();
        recordP3Trail();
        renderAll();

        // Redraw immediately when switching Bootstrap navbar tabs or resizing
        document.addEventListener('shown.bs.tab', () => {
          setTimeout(renderAll, 20);
        });
        window.addEventListener('resize', renderAll);
      });
    })();
  "))
)

server <- function(input, output, session) {
  
  # --- PANEL 1 OBSERVERS ---
  observe({
    session$sendCustomMessage("syncLabState", list(
      panel = "p1",
      data = list(
        puzzle = as.integer(input$p1_puzzle),
        role = input$p1_role,
        matchMode = input$p1_match_mode,
        showCoords = isTRUE(input$p1_show_coords)
      )
    ))
  })
  
  observeEvent(input$p1_origin_btn, {
    session$sendCustomMessage("syncLabState", list(
      panel = "p1",
      data = list(action = "snap_origin")
    ))
  })
  
  observeEvent(input$p1_reset_btn, {
    session$sendCustomMessage("syncLabState", list(
      panel = "p1",
      data = list(recTail = c(-1, -1), recHead = c(2, 2))
    ))
  })
  
  # --- PANEL 2 OBSERVERS ---
  observe({
    session$sendCustomMessage("syncLabState", list(
      panel = "p2",
      data = list(
        mode = input$p2_mode,
        preset = input$p2_preset,
        flipB = isTRUE(input$p2_flip_b)
      )
    ))
  })
  
  observeEvent(input$p2_reset_pos, {
    session$sendCustomMessage("syncLabState", list(
      panel = "p2",
      data = list(posA = c(0, 0), posB = c(0, 0), posC = c(0, 0))
    ))
  })
  
  # --- PANEL 3 OBSERVERS ---
  observe({
    session$sendCustomMessage("syncLabState", list(
      panel = "p3",
      data = list(
        lockLen = isTRUE(input$p3_lock_len),
        showCurve = isTRUE(input$p3_show_curve)
      )
    ))
  })
  
  observeEvent(input$p3_stretch_a, {
    session$sendCustomMessage("syncLabState", list(
      panel = "p3",
      data = list(action = "stretch_a")
    ))
  })
  
  observeEvent(input$p3_ortho_btn, {
    session$sendCustomMessage("syncLabState", list(
      panel = "p3",
      data = list(action = "ortho")
    ))
  })
  
  observeEvent(input$p3_clear_trail, {
    session$sendCustomMessage("syncLabState", list(
      panel = "p3",
      data = list(action = "clear")
    ))
  })
  
  # --- PANEL 4 OBSERVERS ---
  observe({
    session$sendCustomMessage("syncLabState", list(
      panel = "p4",
      data = list(
        tilt3D = isTRUE(input$p4_tilt_3d),
        showPerp = isTRUE(input$p4_show_perp)
      )
    ))
  })
  
  observeEvent(input$p4_swap_btn, {
    session$sendCustomMessage("syncLabState", list(
      panel = "p4",
      data = list(action = "swap")
    ))
  })
  
  observeEvent(input$p4_reset_cam, {
    session$sendCustomMessage("syncLabState", list(
      panel = "p4",
      data = list(action = "reset")
    ))
  })
}

shinyApp(ui, server)
